"""Global database backup UI: typed native exports, restore plans and separate evidence."""
import json,time
from desktop_fixture import Peer,Desktop,expect,ROOT
out=ROOT/'artifacts/database-ui'
with Peer(out/'peer') as peer:
    config=peer.config([peer.profile('Alpha')],out)
    with Desktop(out/f'desktop-{time.time_ns()}',config) as app:
        p=app.page;p.locator('.rail-backups').click()
        p.get_by_role('button',name='New backup policy',exact=True).click();d=p.get_by_role('dialog',name='Backup policy',exact=True)
        d.get_by_role('textbox',name='Policy name',exact=True).fill('Postgres application')
        d.get_by_role('textbox',name='Repository location',exact=True).fill('/backup/application')
        d.get_by_role('textbox',name='Server password file',exact=True).fill('/secrets/repository')
        d.get_by_role('textbox',name='Source directory',exact=True).fill('/staging')
        d.get_by_role('button',name='PostgreSQL',exact=True).click()
        expect(d.get_by_role('textbox',name='Database port',exact=True)).to_have_value('5432')
        expect(d.get_by_role('textbox',name='Exclude patterns (one per line)',exact=True)).to_have_count(0)
        d.get_by_role('textbox',name='Database name',exact=True).fill('app')
        d.get_by_role('textbox',name='Database user',exact=True).fill('backup')
        d.get_by_role('textbox',name='Database auth file',exact=True).fill('/secrets/pgpass')
        d.locator('.target-choice').first.click();app.screenshot('postgres-policy.png')
        d.get_by_role('button',name='Save policy',exact=True).click()
        expect(p.locator('.backup-policy')).to_contain_text('No saved successful confirmation')
        p.get_by_role('button',name='Back up now',exact=True).click();d=p.get_by_role('dialog',name='Run script on servers',exact=True)
        d.get_by_role('button',name='Check targets',exact=True).click()
        expect(p.locator('.task-status')).to_have_text(['Ready'],timeout=20000)
        expect(p.locator('.task-target')).to_contain_text('pg_dump')
        expect(p.locator('.task-target')).to_contain_text('--format=custom')
        expect(p.locator('.task-target')).to_contain_text('export.sha256')
        p.get_by_role('button',name='Execute ready targets',exact=True).click();expect(p.locator('.task-status')).to_have_text(['Succeeded'],timeout=20000)
        p.locator('.rail-backups').click()
        records=json.loads(app.config.read_text())['config']['backup_evidence'];assert [r['kind'] for r in records]==['Backup']
        p.get_by_role('button',name='Verify repository data',exact=True).click();d=p.get_by_role('dialog',name='Run script on servers',exact=True)
        d.get_by_role('button',name='Check targets',exact=True).click();expect(p.locator('.task-status')).to_have_text(['Ready'],timeout=20000)
        p.get_by_role('button',name='Execute ready targets',exact=True).click();expect(p.locator('.task-status')).to_have_text(['Succeeded'],timeout=20000)
        p.locator('.rail-backups').click();p.get_by_role('button',name='Browse snapshots…',exact=True).click();d=p.get_by_role('dialog',name='Backup snapshots',exact=True)
        d.get_by_role('button',name='Load snapshots',exact=True).click();expect(d.locator('.backup-snapshot')).to_have_count(1)
        d.get_by_role('button',name='Restore to new PostgreSQL database…',exact=True).click();d=p.get_by_role('dialog',name='Restore PostgreSQL database',exact=True)
        d.get_by_role('textbox',name='New database name',exact=True).fill('app')
        d.get_by_role('button',name='Review database restore…',exact=True).click();expect(d).to_contain_text('different from the source')
        d.get_by_role('textbox',name='New database name',exact=True).fill('app_rehearsal')
        d.get_by_role('textbox',name='Database user',exact=True).fill('restore_role')
        d.get_by_role('textbox',name='Database auth file',exact=True).fill('/secrets/restore-pgpass')
        app.screenshot('postgres-restore.png')
        d.get_by_role('button',name='Review database restore…',exact=True).click();d=p.get_by_role('dialog',name='Run script on servers',exact=True)
        d.get_by_role('button',name='Check targets',exact=True).click();expect(p.locator('.task-status')).to_have_text(['Ready'],timeout=20000)
        expect(p.locator('.task-target')).to_contain_text('createdb')
        expect(p.locator('.task-target')).to_contain_text('--single-transaction')
        expect(p.locator('.task-target')).to_contain_text('app_rehearsal')
        p.get_by_role('button',name='Execute ready targets',exact=True).click();expect(p.locator('.task-status')).to_have_text(['Succeeded'],timeout=20000)
        p.locator('.rail-backups').click()
        records=json.loads(app.config.read_text())['config']['backup_evidence'];assert {r['kind'] for r in records}=={'Backup','IntegrityCheck','DatabaseRestore'}
        assert all(r['last_success']['exit_code']==0 for r in records)
        assert next(r for r in records if r['kind']=='DatabaseRestore')['last_success']['destination'].endswith('/app_rehearsal')
        assert next(r for r in records if r['kind']=='Backup')['last_success']['snapshot']=='a'*64
        old_success=next(r['last_success']['task'] for r in records if r['kind']=='Backup')
        p.get_by_role('button',name='Edit',exact=True).click();d=p.get_by_role('dialog',name='Backup policy',exact=True)
        d.get_by_role('textbox',name='Database name',exact=True).fill('fixture-command-fail');d.get_by_role('button',name='Save policy',exact=True).click()
        expect(p.locator('.backup-policy')).to_contain_text('Earlier policy settings')
        p.get_by_role('button',name='Back up now',exact=True).click();d=p.get_by_role('dialog',name='Run script on servers',exact=True)
        d.get_by_role('button',name='Check targets',exact=True).click();expect(p.locator('.task-status')).to_have_text(['Ready'],timeout=20000)
        p.get_by_role('button',name='Execute ready targets',exact=True).click();expect(p.locator('.task-status')).to_have_text(['Failed'],timeout=20000)
        p.locator('.rail-backups').click()
        records=json.loads(app.config.read_text())['config']['backup_evidence'];backup=next(r for r in records if r['kind']=='Backup')
        assert backup['latest']['status']=='Failed' and backup['last_success']['task']==old_success
        app.screenshot('independent-confirmations.png')
        p.get_by_role('button',name='New backup policy',exact=True).click();d=p.get_by_role('dialog',name='Backup policy',exact=True)
        d.get_by_role('textbox',name='Policy name',exact=True).fill('MySQL application')
        d.get_by_role('textbox',name='Repository location',exact=True).fill('/backup/mysql')
        d.get_by_role('textbox',name='Server password file',exact=True).fill('/secrets/repository')
        d.get_by_role('textbox',name='Source directory',exact=True).fill('/staging')
        d.get_by_role('button',name='MySQL / MariaDB',exact=True).click();expect(d.get_by_role('textbox',name='Database port',exact=True)).to_have_value('3306')
        d.get_by_role('textbox',name='Database name',exact=True).fill('app');d.get_by_role('textbox',name='Database user',exact=True).fill('backup');d.get_by_role('textbox',name='Database auth file',exact=True).fill('/secrets/mysql.cnf')
        d.locator('.target-choice').first.click();d.get_by_role('button',name='Save policy',exact=True).click()
        mysql=p.locator('.backup-policy').filter(has_text='MySQL application');mysql.get_by_role('button',name='Back up now',exact=True).click();d=p.get_by_role('dialog',name='Run script on servers',exact=True)
        d.get_by_role('button',name='Check targets',exact=True).click();expect(p.locator('.task-status')).to_have_text(['Ready'],timeout=20000)
        expect(p.locator('.task-target')).to_contain_text('--single-transaction');expect(p.locator('.task-target')).to_contain_text('--defaults-file=')
        p.get_by_role('button',name='Stop pending targets',exact=True).click();expect(p.locator('.task-status')).to_have_text(['Cancelled'])
        p.locator('.rail-backups').click();app.stop();app.launch();p=app.page;p.locator('.rail-backups').click()
        expect(p.locator('.backup-policy')).to_have_count(2);expect(p.locator('.backup-policy').first).to_contain_text('Failed')
        p.get_by_role('button',name='Database client installers…',exact=True).click()
        expect(p.locator('.script-row')).to_have_count(2)
        expect(p.locator('.script-page')).to_contain_text('Install PostgreSQL client')
        expect(p.locator('.script-page')).to_contain_text('Install MySQL/MariaDB client')
        app.settings('General');p.locator('.setting-language:visible').get_by_role('radio', name='简体中文', exact=True).check();expect(p.locator('.page-header-title')).to_have_text('常规')
        p.locator('.rail-backups').click();p.set_viewport_size(dict(width=900,height=700));assert p.evaluate('document.documentElement.scrollWidth <= innerWidth');app.screenshot('database-chinese.png')
        p.get_by_role('button',name='数据库客户端安装模板…',exact=True).click()
        p.get_by_role('textbox',name='搜索脚本',exact=True).fill('PostgreSQL 客户端')
        expect(p.locator('.script-row')).to_have_count(1)
        text=app.config.read_text()+app.config.with_suffix('.tasks.json').read_text();assert 'arcnix-db-test-password' not in text
(out/'results.json').write_text(json.dumps(dict(passed=True,checks=['PostgreSQL policy fields','native custom archive export plan','independent backup evidence','full repository check evidence','snapshot engine tags','new-database restore target','reject source database name','typed restore role and password file','restore confirmation stays separate','failed attempts preserve success','policy scope changes visible','MySQL transactional export plan','restart evidence persistence','Chinese narrow layout','no credential values persisted','database client installer entry','localized official script search']),indent=2))
print('17 database UI checks passed')
